import { componentAttrs } from "../_utils/component.helper";

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function resolveLink(link) {
  if (!link) return null;
  if (typeof link === "string") return { url: link, target: "_self" };
  if (typeof link === "object" && link.url)
    return { url: link.url, target: link.target || "_self" };
  return null;
}

/**
 * Font Awesome classic/thin, per this project's icon convention -- not an
 * inline SVG. Matches the reference implementation's own icon exactly
 * (Icon name="right-from-bracket"), which wasn't achievable when this was
 * first built (no Font Awesome kit wired up at the time).
 */
const ICON_SVG =
  '<i class="fa-thin fa-right-from-bracket" aria-hidden="true"></i>';

export default {
  async main(input = {}) {
    const { Quick_Exit: quickExit = {} } = input;
    const {
      label = "Quick exit",
      message = "Click anywhere in this banner to exit. Call 000 if you're in immediate danger.",
      exitUrl = "https://www.google.com",
      whatIsThisHref = null,
      ariaLabel = "",
    } = quickExit;

    const resolvedExit = resolveLink(exitUrl) || {
      url: "https://www.google.com",
      target: "_self",
    };
    const resolvedWhatIsThis = resolveLink(whatIsThisHref);

    const regionLabel = ariaLabel || label;

    const whatIsThisHtml = resolvedWhatIsThis
      ? `<a class="quick-exit__link" href="${esc(resolvedWhatIsThis.url)}"${resolvedWhatIsThis.target !== "_self" ? ` target="${esc(resolvedWhatIsThis.target)}" rel="noopener noreferrer"` : ""}>What is this?</a>`
      : "";

    return /*html*/ `
<div ${componentAttrs("quick-exit", input)} class="fullwidth" role="region" aria-label="${esc(regionLabel)}">
  <button type="button" class="quick-exit__action" data-quick-exit-url="${esc(resolvedExit.url)}">
    <div class="quick-exit__heading">
      <span class="quick-exit__icon" aria-hidden="true">${ICON_SVG}</span>
      <span class="quick-exit__title" data-sq-field="label">${esc(label)}</span>
    </div>
    <p class="quick-exit__message" data-sq-field="message">${esc(message)}</p>
  </button>
  ${whatIsThisHtml}
</div>
`;
  },
};
